import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  makeNativeStartupProbe,
  NATIVE_STARTUP_BOUNDARY,
  NATIVE_STARTUP_INSTANCE,
} from "./NativeStartupProbe.ts";

readonly nativeProbe?: ReturnType<typeof makeNativeStartupProbe>;
readonly nativeHomeDir?: string;
readonly projectWorkspaceRoot?: string;

input?.nativeProbe?.coordinatorLayer ??
  (input?.threadLease
    ? Layer.effect(
        TurnCheckpointCoordinator,
        Effect.gen(function* () {
          const coordinator = yield* TurnCheckpointCoordinator;
          return { ...coordinator, withThreadLease: input.threadLease! };
        }),
      ).pipe(Layer.provide(TurnCheckpointCoordinatorLive))
    : TurnCheckpointCoordinatorLive),

  input?.nativeProbe?.checkpointLayer ?? Layer.succeed(CheckpointStore, checkpointStore),
),
Layer.provideMerge(
  input?.nativeProbe?.gitLayer ??
    Layer.succeed(GitCore, {
      renameBranch,
      publishBranch,
      withMutation,
    } as unknown as GitCoreShape),

nativeProvider: input?.nativeProbe
  ? await runtime.runPromise(Effect.service(ProviderService))
  : undefined,
nativeCheckpointStore: input?.nativeProbe
  ? await runtime.runPromise(Effect.service(CheckpointStore))
  : undefined,
disposeNative: async () => {
  await Effect.runPromise(Scope.close(harnessScope, Exit.void));
  scopes.delete(harnessScope);
  await runtime.dispose();
  runtimes.delete(runtime);
},

describe.runIf(process.env.SYNARA_NATIVE_STARTUP_PROBE === "1")(
  "native startup phase measurement",
  () => {
    const threadId = ThreadId.makeUnsafe("thread-1");
    const modelSelection = {
      provider: "opencode" as const,
      model: "opencode/mimo-v2.6-flash-free",
      instanceId: NATIVE_STARTUP_INSTANCE,
    };

    async function nativeHarness(name: string, startReactor = true) {
      const probe = makeNativeStartupProbe(name);
      const baseDir = fs.mkdtempSync(path.join(os.tmpdir(), "synara-native-startup-"));
      const cwd = path.join(baseDir, "repository");
      const homeDir = path.join(baseDir, "home");
      fs.mkdirSync(cwd);
      fs.mkdirSync(homeDir);
      const git = (args: string[]) => {
        const result = spawnSync("git", args, {
          cwd,
          shell: false,
          timeout: 30_000,
          encoding: "utf8",
          maxBuffer: 1_000_000,
        });
        expect(result.error).toBeUndefined();
        expect(result.signal).toBeNull();
        expect(result.status, result.stderr).toBe(0);
        return result.stdout.trim();
      };
      git(["init", "--initial-branch=probe"]);
      git(["config", "user.name", "Native startup diagnostic"]);
      git(["config", "user.email", "native-startup@example.invalid"]);
      git(["config", "core.autocrlf", "false"]);
      const fileNames = Array.from(
        { length: 512 },
        (_, index) => `fixture-${String(index).padStart(4, "0")}.txt`,
      );
      for (const [index, file] of fileNames.entries()) {
        fs.writeFileSync(path.join(cwd, file), Buffer.alloc(4096, 65 + (index % 26)));
      }
      git(["add", "--all"]);
      git(["commit", "-m", "Create bounded local checkpoint workload"]);
      for (const file of fileNames.slice(0, 256)) {
        fs.writeFileSync(path.join(cwd, file), Buffer.alloc(4096, 97));
      }
      const fingerprint = () => {
        const hash = createHash("sha256");
        for (const file of fileNames)
          hash
            .update(file)
            .update("\0")
            .update(fs.readFileSync(path.join(cwd, file)));
        return hash.digest("hex");
      };
      const initialFingerprint = fingerprint();
      probe.record("workload", {
        files: fileNames.length,
        bytesPerFile: 4096,
        totalBytes: 512 * 4096,
        modifiedFiles: 256,
        contentSha256: initialFingerprint,
        gitVersion: git(["--version"]),
        localCommit: git(["rev-parse", "HEAD"]),
        remotes: git(["remote"]),
      });
      const harness = await createHarness({
        baseDir,
        nativeProbe: probe,
        nativeHomeDir: homeDir,
        projectWorkspaceRoot: cwd,
        threadModelSelection: modelSelection,
        startReactor,
        ingestRuntimeEvents: true,
        // The existing mock harness uses zero; native measurements restore the
        // production grace. Lease30s, command120s, baseline5s stay at defaults.
        commandSettleGrace: Duration.seconds(15),
        serverSettings: {
          providerInstances: {
            [NATIVE_STARTUP_INSTANCE]: {
              driver: "opencode",
              enabled: true,
              config: { binaryPath: probe.binary },
            },
          },
        },
      });
      expect(harness.nativeProvider).toBeDefined();
      expect(harness.nativeCheckpointStore).toBeDefined();
      return { harness, probe, cwd, fingerprint, initialFingerprint };
    }

    async function finishNative(
      owned: Awaited<ReturnType<typeof nativeHarness>>,
      body: () => Promise<void>,
    ) {
      const errors: unknown[] = [];
      try {
        await body();
      } catch (error) {
        errors.push(error);
      }
      try {
        await owned.harness.disposeNative();
        owned.probe.assertOwnedExit();
        expect(owned.fingerprint()).toBe(owned.initialFingerprint);
      } catch (error) {
        errors.push(error);
      }
      owned.probe.record("case-result", {
        passed: errors.length === 0,
        errorCount: errors.length,
      });
      if (errors.length > 0)
        throw new AggregateError(
          errors,
          "Native phase measurement failed; preserve all observations",
        );
    }

    const dispatch = (harness: Awaited<ReturnType<typeof createHarness>>, id: string) =>
      Effect.runPromise(
        harness.engine.dispatch({
          type: "thread.turn.start",
          runtimeMode: "approval-required",
          interactionMode: "default",
          commandId: CommandId.makeUnsafe(`native-${id}`),
          threadId,
          message: {
            messageId: MessageId.makeUnsafe(`native-message-${id}`),
            role: "user",
            text: "Diagnostic admission boundary; do not write a native prompt.",
            attachments: [],
          },
          createdAt: new Date().toISOString(),
        }),
      );

    const waitForRefusal = async (
      owned: Awaited<ReturnType<typeof nativeHarness>>,
      boundaries: number,
    ) => {
      await waitFor(() => owned.probe.promptBoundaries() === boundaries, 80_000);
      await owned.harness.drain();
      const thread = await readHarnessThread(owned.harness);
      expect(
        thread?.activities.some(
          (activity) =>
            activity.kind === "provider.turn.start.failed" &&
            JSON.stringify(activity).includes(NATIVE_STARTUP_BOUNDARY),
        ),
      ).toBe(true);
      expect(String(thread?.session?.lastError ?? "")).not.toContain("uncertain");
    };

    it("measures real cold admission, checkpoint prelude, warm reuse and final owned exit", async () => {
      const owned = await nativeHarness("cold-warm");
      await finishNative(owned, async () => {
        owned.probe.record("dispatch-start");
        await dispatch(owned.harness, "cold");
        await waitForRefusal(owned, 1);
        expect(owned.probe.adapterStarts()).toBe(1);
        expect(
          owned.probe.observations.some(
            (entry) =>
              entry.kind === "phase-end" &&
              entry.phase === "checkpoint.capture" &&
              entry.exit === "Success",
          ),
        ).toBe(true);
        const beforeStop = await Effect.runPromise(owned.probe.observeChildren());
        expect(beforeStop).toHaveLength(1);
        expect(beforeStop[0]?.running).toBe(true);
        const provider = owned.harness.nativeProvider!;
        expect(provider.stopRuntimeSession).toBeDefined();
        owned.probe.setScenario("adapter-stop-with-pool-warm");
        await Effect.runPromise(
          owned.probe.trace("provider.runtime-stop", provider.stopRuntimeSession!({ threadId })),
        );
        const afterStop = await Effect.runPromise(owned.probe.observeChildren());
        owned.probe.record("warm-pool-observation", { children: afterStop });
        expect(afterStop).toEqual(beforeStop);
        owned.probe.setScenario("warm-admission");
        owned.probe.record("dispatch-start");
        await dispatch(owned.harness, "warm");
        await waitForRefusal(owned, 2);
        expect(owned.probe.adapterStarts()).toBe(2);
        const afterResume = await Effect.runPromise(owned.probe.observeChildren());
        expect(afterResume).toEqual(beforeStop);
        owned.probe.record("warm-reuse-observation", { children: afterResume });
        owned.probe.setScenario("runtime-pool-disposal");
      });
    }, 240_000);

    it("measures the unchanged thirty-second lease under an explicitly controlled checkpoint hold", async () => {
      const owned = await nativeHarness("lease-contention");
      await finishNative(owned, async () => {
        const acquired = Deferred.makeUnsafe<void>();
        const release = Deferred.makeUnsafe<void>();
        const checkpoint = owned.harness.nativeCheckpointStore!;
        const holder = Effect.runFork(
          owned.harness.checkpointCoordinator.withThreadLease(
            threadId,
            Effect.gen(function* () {
              yield* Deferred.succeed(acquired, undefined);
              yield* checkpoint.captureCheckpoint({
                cwd: owned.cwd,
                checkpointRef: checkpointRefForThreadTurn(
                  ThreadId.makeUnsafe("native-contention-owner"),
                  0,
                ),
              });
              yield* Effect.sync(() => owned.probe.record("controlled-checkpoint-hold-start"));
              yield* Deferred.await(release);
            }),
          ),
        );
        try {
          await Effect.runPromise(
            Deferred.await(acquired).pipe(Effect.timeout(Duration.seconds(10))),
          );
          const started = performance.now();
          owned.probe.record("dispatch-start");
          await dispatch(owned.harness, "lease-held");
          await waitFor(
            async () =>
              (await readHarnessThread(owned.harness))?.activities.some(
                (activity) =>
                  activity.kind === "provider.turn.start.failed" &&
                  JSON.stringify(activity).includes("30000ms"),
              ) === true,
            45_000,
          );
          const elapsedMs = performance.now() - started;
          owned.probe.record("lease-timeout-observed", { elapsedMs, configuredLeaseMs: 30_000 });
          expect(elapsedMs).toBeGreaterThanOrEqual(29_500);
          expect(owned.probe.adapterStarts()).toBe(0);
          expect(owned.probe.promptBoundaries()).toBe(0);
        } finally {
          await Effect.runPromise(Deferred.succeed(release, undefined));
          await Effect.runPromise(Fiber.join(holder));
          owned.probe.record("controlled-checkpoint-hold-ended");
        }
        await owned.harness.drain();
        owned.probe.setScenario("post-contention-admission");
        owned.probe.record("dispatch-start");
        await dispatch(owned.harness, "after-contention");
        await waitForRefusal(owned, 1);
        expect(owned.probe.adapterStarts()).toBe(1);
      });
    }, 240_000);

    it("measures owned cancellation after a real readiness response before session admission", async () => {
      const owned = await nativeHarness("startup-cancellation", false);
      await finishNative(owned, async () => {
        const reachedReadiness = owned.probe.armReadinessCancellation();
        const fiber = Effect.runFork(
          owned.harness.nativeProvider!.startSession(threadId, {
            provider: "opencode",
            providerInstanceId: NATIVE_STARTUP_INSTANCE,
            threadId,
            cwd: owned.cwd,
            runtimeMode: "approval-required",
            modelSelection,
          }),
        );
        try {
          await Effect.runPromise(
            Deferred.await(reachedReadiness).pipe(Effect.timeout(Duration.seconds(30))),
          );
          owned.probe.record("caller-cancellation-requested");
          await Effect.runPromise(
            owned.probe.trace("provider.startup-cancellation", Fiber.interrupt(fiber)),
          );
          const exit = await Effect.runPromise(Fiber.await(fiber));
          expect(Exit.isFailure(exit)).toBe(true);
          expect(owned.probe.adapterStarts()).toBe(0);
          expect(owned.probe.promptBoundaries()).toBe(0);
        } finally {
          await Effect.runPromise(Fiber.interrupt(fiber));
        }
      });
    }, 120_000);
  },
);
